import {crystalShapes,crystalColors,stickerMotifs,metalColors,beadSizes,singleCharacter,previewCanvas} from './objects.js';
export const gemShapes=['round','oval','square','diamond','heart','star','teardrop','pearl'];
export const gemColors={clear:'#e5e4dc',ruby:'#a92e46',sapphire:'#4055a1',emerald:'#47795d',amber:'#bf883e',rose:'#d99caa',onyx:'#28292d',pearl:'#eee0c8'};
export const normalizeHex=v=>typeof v==='string'&&/^#?[\da-f]{6}$/i.test(v.trim())?'#'+v.trim().replace('#','').toUpperCase():null;
export function recentColor(list,color){const hex=normalizeHex(color);return hex?[hex,...list.filter(c=>c!==hex)].slice(0,5):list;}
export function gemPath(shape){return {round:'M0 -10 A10 10 0 1 1 -.01 -10Z',oval:'M0 -12 C12 -12 12 12 0 12 C-12 12 -12 -12 0 -12Z',square:'M-9 -9H9V9H-9Z',diamond:'M0 -12 9 0 0 12 -9 0Z',heart:'M0 10 C-19 -2 -9 -15 0 -5 C9 -15 19 -2 0 10Z',star:'M0 -12 3 -4 11 -4 5 2 7 10 0 5 -7 10 -5 2 -11 -4 -3 -4Z',teardrop:'M0 -13 C3 -7 10 -1 9 5 C7 14 -7 14 -9 5 C-10 -1 -3 -7 0 -13Z',pearl:'M0 -10 A10 10 0 1 1 -.01 -10Z'}[shape]||'';}
export function gemSVG(shape,color){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-16 -16 32 32"><path d="${gemPath(shape)}" fill="${color}" fill-opacity=".88" stroke="#8b7664" stroke-width=".65"/><path d="M-7 -5 L0 -8 6 -3 4 5 -4 5Z M-7 -5 -4 5 M0 -8 0 1 6 -3 M0 1 4 5 M0 1 -4 5" fill="#fff" fill-opacity=".12" stroke="#fff" stroke-opacity=".5" stroke-width=".6"/><ellipse cx="-4" cy="-5" rx="2" ry="1" fill="#fff8"/></svg>`;}
export function createWorkstation(api){
 const {root,pickColor,pickGem,save}=api;let recent=[],custom=null,shape='round',gemColor=gemColors.clear,gemSize=1,category='crystals',crystalFinish='plain',motif='star',letter='A',stickerInk='black',stickerColor='#171918',beadSize='S',metalFinish='silver';
 const settings={brush:{size:1,opacity:1},liner:{size:1,opacity:1},dot:{size:1,spacing:2.2},fan:{size:1,density:1},erase:{size:1}};
 const center=document.createElement('section');center.id='context-zone';center.setAttribute('aria-label','Selected tool options');root.querySelector('.table-objects').insertBefore(center,root.querySelector('.tool-zone'));
 const add=document.createElement('button');add.id='custom-polish';add.textContent='+ custom';add.onclick=()=>openPicker('polish');root.querySelector('.tray-caption').append(add);
 const picker=document.createElement('form');picker.id='color-picker';picker.hidden=true;picker.innerHTML='<label>custom <span id="color-for"></span><input type="color" aria-label="Visual color and hue picker" value="#6f83c8"></label><label class="hex-label">HEX <input aria-label="Hex color" value="#6F83C8" maxlength="7" spellcheck="false"></label><span class="color-error" role="status"></span><div><button type="button" data-close>cancel</button><button type="submit">use color ↗</button></div>';root.append(picker);let destination='polish';
 const visual=picker.querySelector('[type=color]'),hex=picker.querySelector('[maxlength]');visual.oninput=()=>{hex.value=visual.value.toUpperCase();picker.querySelector('.color-error').textContent='';};hex.oninput=()=>{const c=normalizeHex(hex.value);if(c)visual.value=c;};picker.querySelector('[data-close]').onclick=()=>picker.hidden=true;
 function openPicker(forWhat){destination=forWhat;picker.querySelector('#color-for').textContent=forWhat;visual.value=forWhat==='gem'?gemColor:forWhat==='sticker'?stickerColor:custom||'#6F83C8';hex.value=visual.value.toUpperCase();picker.hidden=false;hex.focus();}
 picker.onsubmit=e=>{e.preventDefault();const c=normalizeHex(hex.value);if(!c){picker.querySelector('.color-error').textContent='Use six hexadecimal digits, e.g. #6F83C8.';return;}if(destination==='polish'){custom=c;recent=recentColor(recent,c);renderBottles();pickColor(c);}else{if(destination==='sticker'){stickerColor=c;stickerInk='custom';}else{gemColor=c;crystalFinish='plain';}render(api.tool());chooseObject();}picker.hidden=true;save();};
 function renderBottles(){root.querySelectorAll('.custom-bottle').forEach(b=>b.remove());recent.forEach(c=>{const b=document.createElement('button');b.className='bottle custom-bottle';b.style.setProperty('--color',c);b.style.setProperty('--angle','-3deg');b.dataset.hex=c;b.setAttribute('aria-label','Custom '+c+' polish');b.setAttribute('aria-pressed',custom===c);b.innerHTML='<span class="glass"></span><span class="cap"></span>';b.onclick=()=>{custom=c;pickColor(c);};root.querySelector('#tray').append(b);});}
 function range(label,value,min,max,step,change){const l=document.createElement('label');l.className='context-range';const title=document.createElement('span');title.textContent=label;const input=document.createElement('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=value;input.setAttribute('aria-label',label);input.oninput=()=>{change(+input.value);save();};l.append(title,input);center.append(l);}
 function render(tool){center.replaceChildren();root.dataset.tool=tool;const name=document.createElement('span');name.className='category';name.textContent=tool==='pick'?'objects':tool==='extend'?'shape / length':tool==='stamp'?'transfer':tool==='erase'?'clean':tool;center.append(name);
 if(settings[tool]){range('size',settings[tool].size,.3,1.5,.05,v=>settings[tool].size=v);const key=tool==='dot'?'spacing':tool==='fan'?'density':tool==='erase'?null:'opacity';if(key)range(key,settings[tool][key],key==='spacing'?1.1:.1,key==='spacing'?5:1,.05,v=>settings[tool][key]=v);}
 else if(tool==='pick')renderObjects();
 else if(tool==='extend')api.renderShape(center);
 else{const p=document.createElement('p');p.textContent='Press a design to load. Press another nail to transfer. Tap the stamper to mirror.';center.append(p);}}
 function objectConfig(){return category==='stickers'?{type:'sticker',motif,letter,color:stickerInk==='black'?'#171918':stickerInk==='white'?'#fffaf0':stickerInk==='current'?api.currentColor():stickerColor,scale:gemSize}:category==='metal'?{type:'steel-bead',size:beadSize,finish:metalFinish,scale:gemSize}:{type:'gem',shape,color:gemColor,finish:crystalFinish,scale:gemSize};}
 function chooseObject(){pickGem(objectConfig());save();}
 function labels(items,value,change,className='editorial-options'){const row=document.createElement('div');row.className=className;for(const [key,label] of items){const button=document.createElement('button');button.textContent=label;button.setAttribute('aria-pressed',key===value);button.onclick=()=>change(key);row.append(button);}center.append(row);return row;}
 function renderObjects(){
 labels([['crystals','crystals'],['stickers','stickers'],['metal','metal']],category,v=>{category=v;api.cancelObject();root.classList.remove('show-objects');render('pick');save();},'object-tabs');
 const shapes=document.createElement('div');shapes.className='object-sheet';shapes.setAttribute('aria-label',category+' tray');
 if(category==='crystals'||category==='stickers'){const entries=category==='crystals'?crystalShapes:stickerMotifs;entries.forEach(value=>{const config={...objectConfig(),...(category==='crystals'?{shape:value}:{motif:value})},button=document.createElement('button');button.append(previewCanvas(config));const label=document.createElement('span');label.textContent=value==='statement'?'statement gem':value;button.append(label);button.setAttribute('aria-label',category==='crystals'?value==='statement'?'Statement gem':value+' crystal':value+' sticker');button.setAttribute('aria-pressed',value===(category==='crystals'?shape:motif));button.onclick=()=>{if(category==='crystals')shape=value;else motif=value;render('pick');chooseObject();};shapes.append(button);});center.append(shapes);const active=shapes.querySelector('[aria-pressed=true]');if(active)shapes.scrollLeft=Math.max(0,active.offsetLeft-shapes.firstElementChild.offsetLeft-(shapes.clientWidth-active.offsetWidth)/2);}
 if(category==='crystals'){const colors=document.createElement('div');colors.className='gem-colors';Object.entries(crystalColors).forEach(([name,color])=>{const button=document.createElement('button');button.style.setProperty('--gem',color);button.dataset.finish=name;button.setAttribute('aria-label',name==='ab'?'AB iridescent crystal color':name+' crystal color');button.title=name==='ab'?'AB / iridescent':name;button.setAttribute('aria-pressed',name==='ab'?crystalFinish==='ab':crystalFinish!=='ab'&&normalizeHex(color)===normalizeHex(gemColor));button.onclick=()=>{gemColor=color;crystalFinish=name==='ab'?'ab':'plain';render('pick');chooseObject();};colors.append(button);});const custom=document.createElement('button');custom.textContent='+';custom.setAttribute('aria-label','Custom crystal color');custom.onclick=()=>openPicker('gem');colors.append(custom);center.append(colors);}
 else if(category==='stickers'){labels([['black','black'],['white','white'],['current','current color'],['custom','custom']],stickerInk,v=>{stickerInk=v;if(v==='custom')openPicker('sticker');else{render('pick');chooseObject();}});if(motif==='letter'){const label=document.createElement('label');label.className='letter-label';label.textContent='one character ';const input=document.createElement('input');input.value=letter;input.setAttribute('aria-label','Letter sticker character');input.oninput=()=>{letter=singleCharacter(input.value);input.value=letter;chooseObject();};label.append(input);center.append(label);}}
 else{const button=document.createElement('button');button.className='steel-sample';button.append(previewCanvas(objectConfig()));const label=document.createElement('span');label.textContent='steel bead';button.append(label);button.setAttribute('aria-label','Steel bead');button.onclick=chooseObject;center.append(button);labels(Object.keys(beadSizes).map(v=>[v,v]),beadSize,v=>{beadSize=v;render('pick');chooseObject();});labels(Object.keys(metalColors).map(v=>[v,v]),metalFinish,v=>{metalFinish=v;render('pick');chooseObject();});}
 range('object size',gemSize,.7,1.4,.05,v=>{gemSize=v;api.sizeGem(v);});const note=document.createElement('p');note.textContent='Tap to place. Select PICK again to move objects.';center.append(note);if(category==='metal'){const other=document.createElement('button');other.className='more-objects';other.textContent='chains & original objects ↗';other.onclick=()=>root.classList.toggle('show-objects');center.append(other);}
 }

 return {render,settings,selectColor(c){custom=typeof c==='string'?c:null;root.querySelectorAll('.custom-bottle').forEach(b=>{b.classList.toggle('selected',b.dataset.hex===custom);b.setAttribute('aria-pressed',b.dataset.hex===custom);});},state:()=>({recent,custom,shape,gemColor,gemSize,settings,category,crystalFinish,motif,letter,stickerInk,stickerColor,beadSize,metalFinish}),restore(data){if(!data)return;recent=(data.recent||[]).map(normalizeHex).filter(Boolean).slice(0,5);custom=normalizeHex(data.custom);shape=crystalShapes.includes(data.shape)?data.shape:'round';category=['crystals','stickers','metal'].includes(data.category)?data.category:'crystals';crystalFinish=data.crystalFinish==='ab'?'ab':'plain';motif=stickerMotifs.includes(data.motif)?data.motif:'star';letter=singleCharacter(data.letter);stickerInk=['black','white','current','custom'].includes(data.stickerInk)?data.stickerInk:'black';stickerColor=normalizeHex(data.stickerColor)||'#171918';beadSize=Object.hasOwn(beadSizes,data.beadSize)?data.beadSize:'S';metalFinish=Object.hasOwn(metalColors,data.metalFinish)?data.metalFinish:'silver';gemColor=normalizeHex(data.gemColor)||gemColors.clear;gemSize=Math.max(.7,Math.min(1.4,Number(data.gemSize)||1));for(const [t,values] of Object.entries(settings))for(const key of Object.keys(values)){const v=data.settings?.[t]?.[key];if(Number.isFinite(v))values[key]=Math.max(key==='spacing'?1.1:.1,Math.min(key==='spacing'?5:key==='size'?1.5:1,v));}renderBottles();},reset(){recent=[];custom=null;shape='round';gemColor=gemColors.clear;gemSize=1;category='crystals';crystalFinish='plain';motif='star';letter='A';stickerInk='black';stickerColor='#171918';beadSize='S';metalFinish='silver';for(const [tool,values] of Object.entries(settings))for(const key of Object.keys(values))values[key]=key==='spacing'?2.2:1;root.classList.remove('show-objects');renderBottles();picker.hidden=true;},close(){picker.hidden=true;}};
}
